local function dumpInstance(instance, log, indent)
    indent = indent or S(179)
    for _, child in ipairs(instance:GetChildren()) do
        local line = indent .. child.ClassName .. S(22) .. child.Name .. S(166)
        if child:IsA(S(180)) then
            line = line .. string.format(
                S(20),
                child.ActionText, child.ObjectText, tostring(child.HoldDuration)
            )
        elseif child:IsA(S(21)) then
            line = line .. string.format(S(160), tostring(child.MaxActivationDistance))
        elseif child:IsA(S(91)) or child:IsA(S(193)) then
            line = line .. S(137)
        end
        log(line)
        for attrName, attrValue in pairs(child:GetAttributes()) do
            log(indent .. S(198) .. attrName .. S(17) .. tostring(attrValue))
        end
        dumpInstance(child, log, indent .. S(29))
    end
end
return dumpInstance
end
